import { useCallback, useEffect, useState } from "react";
import { ipc, isTauriRuntime, pickFolder, pickMarkdownFile } from "../lib/ipc";
import type { FileEntry, WorkspaceDescriptor } from "../contracts/types";

export function FileExplorer(props: {
  workspace: WorkspaceDescriptor | null;
  onOpenRelative: (path: string) => void;
  onOpenFolder: (absolutePath: string) => Promise<unknown>;
  onOpenFile: (absolutePath: string) => Promise<unknown>;
  query: string;
  onQuery: (q: string) => void;
  activePath: string;
}) {
  const [entries, setEntries] = useState<FileEntry[]>([]);
  const [busy, setBusy] = useState(false);
  const [hint, setHint] = useState<string | null>(null);
  const tauri = isTauriRuntime();

  const refresh = useCallback(async (ws: WorkspaceDescriptor) => {
    try {
      const list = await ipc.listEntries(ws.id, "");
      setEntries(list);
    } catch {
      setEntries([]);
    }
  }, []);

  useEffect(() => {
    if (props.workspace) {
      void refresh(props.workspace);
      setHint(null);
    } else {
      setEntries([]);
    }
  }, [props.workspace, refresh]);

  const handleOpenFolder = async () => {
    setBusy(true);
    setHint(null);
    try {
      const path = await pickFolder();
      if (!path) {
        setHint("Seleção cancelada.");
        return;
      }
      await props.onOpenFolder(path);
      if (!tauri) {
        setHint("Modo browser: pasta demo simulada (use o app Tauri para o disco real).");
      }
    } catch (e) {
      setHint(e instanceof Error ? e.message : "Erro ao abrir pasta");
    } finally {
      setBusy(false);
    }
  };

  const handleOpenFile = async () => {
    setBusy(true);
    setHint(null);
    try {
      const path = await pickMarkdownFile();
      if (!path) {
        setHint("Seleção cancelada.");
        return;
      }
      await props.onOpenFile(path);
      if (!tauri) {
        setHint("Modo browser: arquivo demo simulado (use o app Tauri para o disco real).");
      }
    } catch (e) {
      setHint(e instanceof Error ? e.message : "Erro ao abrir arquivo");
    } finally {
      setBusy(false);
    }
  };

  const filtered = entries.filter(
    (e) => !props.query || e.name.toLowerCase().includes(props.query.toLowerCase()),
  );

  return (
    <div className="file-explorer">
      <div className="panel-header">
        <h2>Arquivos</h2>
        {props.workspace && (
          <span className="workspace-badge" title={props.workspace.rootLabel}>
            {props.workspace.rootLabel}
          </span>
        )}
      </div>

      <div className="open-actions">
        <button
          type="button"
          className="btn btn-primary"
          onClick={() => void handleOpenFolder()}
          disabled={busy}
          aria-label="Abrir pasta"
        >
          <span className="btn-icon" aria-hidden>
            📁
          </span>
          Abrir pasta
        </button>
        <button
          type="button"
          className="btn btn-secondary"
          onClick={() => void handleOpenFile()}
          disabled={busy}
          aria-label="Abrir arquivo Markdown"
        >
          <span className="btn-icon" aria-hidden>
            📄
          </span>
          Abrir arquivo
        </button>
      </div>

      {!tauri && (
        <p className="banner banner-info" role="status">
          Você está no <strong>browser</strong> (<code>localhost</code>). O botão Abrir funciona em
          modo demo. Para o disco real:{" "}
          <code>./src-tauri/target/release/md-studio</code> ou <code>pnpm tauri dev</code>.
        </p>
      )}

      <label className="field">
        <span>Busca</span>
        <input
          aria-label="Busca no workspace"
          placeholder="Filtrar arquivos…"
          value={props.query}
          onChange={(e) => props.onQuery(e.target.value)}
        />
      </label>

      {hint && (
        <p className="banner banner-muted" role="status">
          {hint}
        </p>
      )}

      <div className="file-list-wrap">
        {!props.workspace && (
          <div className="empty-state">
            <p>Nenhuma pasta aberta</p>
            <p className="muted">Use os botões acima para começar.</p>
          </div>
        )}
        {props.workspace && filtered.length === 0 && (
          <div className="empty-state">
            <p>Nenhum arquivo nesta lista</p>
          </div>
        )}
        <ul className="file-list">
          {filtered.map((e) => (
            <li key={e.relativePath}>
              <button
                type="button"
                className={
                  "file-item" + (props.activePath === e.relativePath ? " is-active" : "")
                }
                onClick={() => props.onOpenRelative(e.relativePath)}
              >
                <span className="file-icon" aria-hidden>
                  {e.kind === "dir" ? "📂" : "📝"}
                </span>
                <span className="file-name">{e.name}</span>
              </button>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}
